export function getFullReadyRecipe(id: string): FullReadyRecipe | undefined {
  return FULL_READY_RECIPES.find(r => r.id === id);
}

export function getFullReadyRecipesByVersion(version: RecipeVersion): FullReadyRecipe[] {
  return FULL_READY_RECIPES.filter(r => r.version === version);
}

export function getFullReadyRecipesByCategory(category: string): FullReadyRecipe[] {
  return FULL_READY_RECIPES.filter(r => r.category === category);
}

export function getFullReadyRecipesByEffort(effort: string): FullReadyRecipe[] {
  return FULL_READY_RECIPES.filter(r => r.effort === effort);
}

export function getFullReadyRecipesByDifficulty(difficulty: string): FullReadyRecipe[] {
  return FULL_READY_RECIPES.filter(r => r.difficulty === difficulty);
}

export function getFullReadyRecipesByTopicWorld(topicWorld: string): FullReadyRecipe[] {
  return FULL_READY_RECIPES.filter(r => r.topicWorld === topicWorld);
}

export function searchFullReadyRecipes(query: string): FullReadyRecipe[] {
  const q = query.toLowerCase();
  return FULL_READY_RECIPES.filter(r =>
    r.name.toLowerCase().includes(q) ||
    r.category.toLowerCase().includes(q) ||
    r.topicWorld.toLowerCase().includes(q) ||
    r.creatorTask.toLowerCase().includes(q) ||
    r.contentAction.toLowerCase().includes(q) ||
    r.transitionFamily.toLowerCase().includes(q)
  );
}

/**
 * Convert a FullReadyRecipe into a ClipRecipe JSONB shape.
 *
 * This copies the full recipe content into the clip's own recipe field,
 * so the planner can edit it per-clip WITHOUT touching the master library.
 *
 * The master library (FULL_READY_RECIPES) is a read-only constant.
 * The clip's recipe is a per-clip copy stored in clips.recipe JSONB.
 */
export function fullReadyRecipeToClipRecipe(fr: FullReadyRecipe): Record<string, unknown> {
  const chainPositions = buildChainPositionsFromRecipe(fr);

  return {
    shotRecipeId: null,
    recordingStyleId: null,
    transitionId: null,
    goal: fr.goal,
    creatorTask: fr.creatorTask,
    prompt: fr.yourContentAction || fr.contentAction,
    exampleResponse: fr.exampleDirections[0] ?? "",
    finalVideoFlow: [...fr.contentShape],
    part1Start: {
      label: "Transition-In",
      instructions: [...fr.part1TransitionIn.steps],
    },
    part2Content: {
      label: "Content Action",
      instructions: [...fr.part2ContentAction.steps],
    },
    part3End: {
      label: "Transition-Out",
      instructions: [...fr.part3TransitionOut.steps],
    },
    beforeRecording: [...fr.recordingSetup],
    recordSteps: [...fr.recordSteps],
    submissionRules: [...fr.whatToSend],
    editStyle: fr.adminEditStyle,
    adminOrder: [...fr.adminEditSteps],
    adminNotes: [fr.transitionRepairRule, fr.creatorFreedomRule].filter(Boolean).join("\n\n"),
    difficulty: fr.difficulty,
    toneMix: [...(fr.toneMix ?? [])],
    whatYouAreMaking: fr.whatYouAreMaking,
    introductionDirection: fr.introductionDirection,
    assignedMovementOrLine: fr.assignedMovementOrLine,
    makeItYourOwn: [...fr.makeItYourOwn],
    exampleDirections: [...fr.exampleDirections],
    // Transition Chain fields
    assemblyMode: fr.assemblyMode,
    chainStrategy: fr.assemblyMode === "Remote Transition Chain" ? "repeating" : undefined,
    participantCount: fr.defaultParticipantCount,
    creatorOrder: [...fr.sixPersonOrder],
    transitionFamily: fr.transitionFamily,
    chainPositions,
    // Store the source recipe ID so we can trace back to the master
    fullReadyRecipeId: fr.id,
    fullReadyRecipeVersion: fr.version,
    // Store the full recipe content for the crew-facing detail view
    fullReadyRecipe: fr,
  };
}

/**
 * Build chain positions from the recipe's assembly plan.
 * Each position gets its role, transition-in/out, and direction.
 */
function buildChainPositionsFromRecipe(fr: FullReadyRecipe) {
  const order = fr.sixPersonOrder.length > 0 ? fr.sixPersonOrder
    : fr.fivePersonFallback.length > 0 ? fr.fivePersonFallback
    : fr.fourPersonFallback;

  return order.map((role, i) => {
    const isFirst = i === 0;
    const isLast = i === order.length - 1;
    const position = i + 1;
    const totalCreators = order.length;

    return {
      name: "", // Admin fills in the creator name
      position,
      totalCreators,
      role,
      previousCreator: isFirst ? null : "",
      nextCreator: isLast ? null : "",
      transitionIn: isFirst ? "Natural opening" : fr.part1TransitionIn.description,
      transitionInSteps: isFirst ? [] : [...fr.part1TransitionIn.steps],
      transitionOut: isLast ? "Final ending" : fr.part3TransitionOut.description,
      transitionOutSteps: isLast ? [] : [...fr.part3TransitionOut.steps],
      direction: "assigned",
      contentAction: fr.yourContentAction || fr.contentAction,
    };
  });
}
